CREATE TABLE IF NOT EXISTS staff (id INTEGER PRIMARY KEY AUTOINCREMENT,full_name TEXT NOT NULL UNIQUE COLLATE NOCASE,username TEXT UNIQUE COLLATE NOCASE,password_hash TEXT,role TEXT NOT NULL CHECK(role IN ('CS LINE','KAPTEN KASIR','CS LC','KASIR')),active INTEGER NOT NULL DEFAULT 1,can_manage INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,staff_id INTEGER NOT NULL REFERENCES staff(id),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL,subtype TEXT, user_id TEXT,nominal INTEGER,proof TEXT,details TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'WAITING' CHECK(status IN ('WAITING','DONE')),created_by INTEGER NOT NULL REFERENCES staff(id),done_by INTEGER REFERENCES staff(id),done_note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,done_at TEXT);
CREATE INDEX IF NOT EXISTS idx_reports_status ON reports(status,created_at);
CREATE INDEX IF NOT EXISTS idx_reports_user ON reports(user_id);
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT,staff_id INTEGER NOT NULL,action TEXT NOT NULL,report_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
